      function requestRenewablesAI(event) {
        var opener=event&&event.currentTarget;
        if(typeof callGemini!=='function'||!opener||!opener.isConnected||opener._ceRenewablesAIRequest)return;
        opener._ceRenewablesAISequence=(opener._ceRenewablesAISequence||0)+1;
        var request={id:String(Date.now())+'-'+opener._ceRenewablesAISequence,signature:rsAISignature};
        opener._ceRenewablesAIRequest=request;
        opener._ceRenewablesAICompleted=null;
        upd({rsAIRequestId:request.id,rsAIStatus:'pending',rsAIResponse:null,rsAIResultSignature:null,rsAICompletedId:null});
        var prompt='You are a hopeful climate science educator for a '+gradeLevel+' student. Analyze this classroom teaching model, not a real-grid forecast. The student designed an energy mix: '+rsSolar+'% solar, '+rsWind+'% wind, '+rsHydro+'% hydro, '+rsNuclear+'% nuclear, '+rsFossil+'% fossil, with storage at '+rsStorage+'/100 and a '+rsTimespan+'-year model timespan. The model firm-capacity index is '+rsReliability+' against its teaching threshold of '+RELIABILITY_TARGET+(rsBrownout?' (below the threshold, indicating brownout risk in this model)':' (at or above the threshold)')+'. Give a 2-3 sentence encouraging analysis that names the trade-off between clean generation and round-the-clock reliability. Mention one real-world country or city using a similar approach without implying this model forecasts its grid. End with an inspiring fact. Keep it under 90 words. Do NOT use markdown.';
        function finish(value) {
          if(!opener.isConnected||opener._ceRenewablesAIRequest!==request||opener.getAttribute('data-ce-renewables-ai-signature')!==request.signature)return;
          opener._ceRenewablesAIRequest=null;
          var message=typeof value==='string'?value.trim():'';
          opener._ceRenewablesAICompleted=message?request.id:null;
          setLabToolData(function(previous){
            var current=previous&&previous.climateExplorer;
            if(!current||current.tab!=='renewables'||current.rsAIRequestId!==request.id||renewablesAISignature(current)!==request.signature)return previous;
            return Object.assign({},previous,{climateExplorer:Object.assign({},current,{rsAIRequestId:null,rsAIStatus:message?'success':'error',rsAIResponse:message||null,rsAIResultSignature:message?request.signature:null,rsAICompletedId:request.id})});
          });
        }
        try { Promise.resolve(callGemini(prompt,true,false,0.8)).then(finish,function(){finish(null);}); }
        catch(error){finish(null);}
      }

