            c.strokeStyle = endGt <= 20 ? 'rgba(110,231,183,0.42)' : 'rgba(125,211,252,0.42)'; c.lineWidth = 1.2; c.stroke();
            c.beginPath(); c.arc(bx, by, 6.2, 0, Math.PI * 2);
