              var returnId = path.deepDiveTriggerId;
              if (returnId !== triggerId) returnId = triggerId;
              if (typeof document === 'undefined' || !document.getElementById(returnId)) returnId = pathPhaseFocusId();
              setPath({ deepDiveSector: null, deepDiveTriggerId: null });
